SELECT 'NAME' key,
'NAME'||'~'||'SHORT_NAME'||'~'||'DESCRIPTION'||'~'||'LEDGER_CATEGORY_CODE'||'~'||'ALC_LEDGER_TYPE_CODE'||'~'||'OBJECT_TYPE_CODE'||'~'||'LE_LEDGER_TYPE_CODE'||'~'||
'COMPLETION_STATUS_CODE'||'~'||'CONFIGURATION_ID'||'~'||'CHART_OF_ACCOUNTS_ID'||'~'||'CURRENCY_CODE'||'~'||'PERIOD_SET_NAME'||'~'||
'ACCOUNTED_PERIOD_TYPE'||'~'||'FIRST_LEDGER_PERIOD_NAME'||'~'||'RET_EARN_CODE_COMBINATION_ID'||'~'||'SUSPENSE_ALLOWED_FLAG'||'~'||
'ALLOW_INTERCOMPANY_POST_FLAG'||'~'||'TRACK_ROUNDING_IMBALANCE_FLAG'||'~'||'ENABLE_AVERAGE_BALANCES_FLAG'||'~'||
'ENABLE_BUDGETARY_CONTROL_FLAG'||'~'||'REQUIRE_BUDGET_JOURNALS_FLAG'||'~'||'ENABLE_JE_APPROVAL_FLAG'||'~'||'ENABLE_AUTOMATIC_TAX_FLAG'||'~'||'CONSOLIDATION_LEDGER_FLAG'||'~'||'TRANSLATE_EOD_FLAG'||'~'||'TRANSLATE_QATD_FLAG'||'~'||'CREATION_DATE'||'~'||'TRANSLATE_YATD_FLAG'||'~'||'CREATED_BY'||'~'||
'LAST_UPDATE_DATE'||'~'||'AUTOMATICALLY_CREATED_FLAG'||'~'||'LAST_UPDATED_BY'||'~'||'BAL_SEG_VALUE_OPTION_CODE'||'~'||'LAST_UPDATE_LOGIN'||'~'||
'BAL_SEG_COLUMN_NAME'||'~'||'OBJECT_VERSION_NUMBER'||'~'||'MGT_SEG_VALUE_OPTION_CODE'||'~'||'MGT_SEG_COLUMN_NAME'||'~'||
'BAL_SEG_VALUE_SET_ID'||'~'||'MGT_SEG_VALUE_SET_ID'||'~'||'IMPLICIT_LEDGER_SET_ID'||'~'||'IMPLICIT_ACCESS_SET_ID'||'~'||
'FUTURE_ENTERABLE_PERIODS_LIMIT'||'~'||'LEDGER_ATTRIBUTES'||'~'||'LEDGER_ID'||'~'||'LATEST_OPENED_PERIOD_NAME'||'~'||'LATEST_ENCUMBRANCE_YEAR'||'~'||
'SLA_ACCOUNTING_METHOD_CODE'||'~'||'SLA_ACCOUNTING_METHOD_TYPE'||'~'||'SLA_DESCRIPTION_LANGUAGE'||'~'||'SLA_ENTERED_CUR_BAL_SUS_CCID'||'~'||
'SLA_BAL_BY_LEDGER_CURR_FLAG'||'~'||'SLA_SEQUENCING_FLAG'||'~'||'SLA_LEDGER_CUR_BAL_SUS_CCID'||'~'||'ENABLE_RECONCILIATION_FLAG'||'~'||
'CREATE_JE_FLAG'||'~'||'SLA_LEDGER_CASH_BASIS_FLAG'||'~'||'COMPLETE_FLAG'||'~'||'USSGL_OPTION_CODE'||'~'||'VALIDATE_JOURNAL_REF_DATE'||'~'||
'JRNLS_GROUP_BY_DATE_FLAG'||'~'||'AUTOREV_AFTER_OPEN_PRD_FLAG'||'~'||'PRIOR_PRD_NOTIFICATION_FLAG'||'~'||'POP_UP_STAT_ACCOUNT_FLAG'||'~'||
'THRESHOLD_AMOUNT'||'~'||'NUMBER_OF_PROCESSORS'||'~'||'PROCESSING_UNIT_SIZE'||'~'||'SEQUENCING_MODE_CODE'||'~'||'ENF_SEQ_DATE_CORRELATION_CODE'||'~'||'NET_CLOSING_BAL_FLAG'||'~'||'CUM_TRANS_CODE_COMBINATION_ID'||'~'||'ROUNDING_CODE_COMBINATION_ID'||'~'||'PERIOD_END_RATE_TYPE'||'~'||'REVAL_FROM_PRI_LGR_CURR'||'~'||'AR_DOC_SEQUENCING_OPTION_FLAG'||'~'||'AP_DOC_SEQUENCING_OPTION_FLAG'||'~'||'ATTRIBUTE_CATEGORY'||'~'||
'ATTRIBUTE1'||'~'||'ATTRIBUTE2'||'~'||'ATTRIBUTE3'||'~'||'ATTRIBUTE4'||'~'||'ATTRIBUTE5'||'~'||'ATTRIBUTE6'||'~'||'ATTRIBUTE7'||'~'||'ATTRIBUTE8'||'~'||'ATTRIBUTE9'||'~'||'ATTRIBUTE10'||'~'||'ATTRIBUTE11'||'~'||'ATTRIBUTE12'||'~'||'ATTRIBUTE13'||'~'||'ATTRIBUTE14'||'~'||'ATTRIBUTE15'||'~'||'ATTRIBUTE_DATE1'||'~'||'ATTRIBUTE_DATE2'||'~'||'ATTRIBUTE_DATE3'||'~'||
'ATTRIBUTE_DATE4'||'~'||'ATTRIBUTE_DATE5'||'~'||'ATTRIBUTE_NUMBER1'||'~'||'ATTRIBUTE_NUMBER2'||'~'||'ATTRIBUTE_NUMBER3'||'~'||'ATTRIBUTE_NUMBER4'||'~'||
'ATTRIBUTE_NUMBER5' LEDGERS
FROM DUAL
UNION ALL
SELECT 'NAME' key,
NAME||'|'||SHORT_NAME||'|'||REPLACE(REPLACE(REPLACE(DESCRIPTION,CHR(10),''),CHR(13),''),'|',' ') ||'|'||LEDGER_CATEGORY_CODE||'|'||ALC_LEDGER_TYPE_CODE||'|'||OBJECT_TYPE_CODE||'|'||LE_LEDGER_TYPE_CODE||'|'||
COMPLETION_STATUS_CODE||'|'||CONFIGURATION_ID||'|'||CHART_OF_ACCOUNTS_ID||'|'||CURRENCY_CODE||'|'||PERIOD_SET_NAME||'|'||
ACCOUNTED_PERIOD_TYPE||'|'||FIRST_LEDGER_PERIOD_NAME||'|'||RET_EARN_CODE_COMBINATION_ID||'|'||SUSPENSE_ALLOWED_FLAG||'|'||
ALLOW_INTERCOMPANY_POST_FLAG||'|'||TRACK_ROUNDING_IMBALANCE_FLAG||'|'||ENABLE_AVERAGE_BALANCES_FLAG||'|'||
ENABLE_BUDGETARY_CONTROL_FLAG||'|'||REQUIRE_BUDGET_JOURNALS_FLAG||'|'||ENABLE_JE_APPROVAL_FLAG||'|'||ENABLE_AUTOMATIC_TAX_FLAG||'|'|| CONSOLIDATION_LEDGER_FLAG||'|'||TRANSLATE_EOD_FLAG||'|'||TRANSLATE_QATD_FLAG||'|'||CREATION_DATE||'|'||TRANSLATE_YATD_FLAG||'|'||CREATED_BY||'|'||
LAST_UPDATE_DATE||'|'||AUTOMATICALLY_CREATED_FLAG||'|'||LAST_UPDATED_BY||'|'||BAL_SEG_VALUE_OPTION_CODE||'|'||LAST_UPDATE_LOGIN||'|'||
BAL_SEG_COLUMN_NAME||'|'||OBJECT_VERSION_NUMBER||'|'||MGT_SEG_VALUE_OPTION_CODE||'|'||MGT_SEG_COLUMN_NAME||'|'||
BAL_SEG_VALUE_SET_ID||'|'||MGT_SEG_VALUE_SET_ID||'|'||IMPLICIT_LEDGER_SET_ID||'|'||IMPLICIT_ACCESS_SET_ID||'|'||
FUTURE_ENTERABLE_PERIODS_LIMIT||'|'||LEDGER_ATTRIBUTES||'|'||LEDGER_ID||'|'||LATEST_OPENED_PERIOD_NAME||'|'||LATEST_ENCUMBRANCE_YEAR||'|'||
SLA_ACCOUNTING_METHOD_CODE||'|'||SLA_ACCOUNTING_METHOD_TYPE||'|'||SLA_DESCRIPTION_LANGUAGE||'|'||SLA_ENTERED_CUR_BAL_SUS_CCID||'|'||
SLA_BAL_BY_LEDGER_CURR_FLAG||'|'||SLA_SEQUENCING_FLAG||'|'||SLA_LEDGER_CUR_BAL_SUS_CCID||'|'||ENABLE_RECONCILIATION_FLAG||'|'||
CREATE_JE_FLAG||'|'||SLA_LEDGER_CASH_BASIS_FLAG||'|'||COMPLETE_FLAG||'|'||USSGL_OPTION_CODE||'|'||VALIDATE_JOURNAL_REF_DATE||'|'||
JRNLS_GROUP_BY_DATE_FLAG||'|'||AUTOREV_AFTER_OPEN_PRD_FLAG||'|'||PRIOR_PRD_NOTIFICATION_FLAG||'|'||POP_UP_STAT_ACCOUNT_FLAG||'|'||
THRESHOLD_AMOUNT||'|'||NUMBER_OF_PROCESSORS||'|'||PROCESSING_UNIT_SIZE||'|'||SEQUENCING_MODE_CODE||'|'||ENF_SEQ_DATE_CORRELATION_CODE||'|'||NET_CLOSING_BAL_FLAG||'|'||CUM_TRANS_CODE_COMBINATION_ID||'|'||ROUNDING_CODE_COMBINATION_ID||'|'||PERIOD_END_RATE_TYPE||'|'||REVAL_FROM_PRI_LGR_CURR||'|'||AR_DOC_SEQUENCING_OPTION_FLAG||'|'||AP_DOC_SEQUENCING_OPTION_FLAG||'|'||ATTRIBUTE_CATEGORY||'|'||
ATTRIBUTE1||'|'||ATTRIBUTE2||'|'||ATTRIBUTE3||'|'||ATTRIBUTE4||'|'||ATTRIBUTE5||'|'||ATTRIBUTE6||'|'||ATTRIBUTE7||'|'||ATTRIBUTE8||'|'||ATTRIBUTE9||'|'||ATTRIBUTE10||'|'||ATTRIBUTE11||'|'||ATTRIBUTE12||'|'||ATTRIBUTE13||'|'||ATTRIBUTE14||'|'||ATTRIBUTE15||'|'||ATTRIBUTE_DATE1||'|'||ATTRIBUTE_DATE2||'|'||ATTRIBUTE_DATE3||'|'||
ATTRIBUTE_DATE4||'|'||ATTRIBUTE_DATE5||'|'||ATTRIBUTE_NUMBER1||'|'||ATTRIBUTE_NUMBER2||'|'||ATTRIBUTE_NUMBER3||'|'||ATTRIBUTE_NUMBER4||'|'||
ATTRIBUTE_NUMBER5
FROM GL_LEDGERS a
WHERE ((:P_FROM_DATE IS NOT NULL AND :P_TO_DATE IS NOT NULL AND a.last_update_date between :P_FROM_DATE AND :P_TO_DATE) or
			(:P_FROM_DATE IS NULL AND :P_TO_DATE IS NULL AND  a.last_update_date > (SELECT MAX(ERH.processstart)
                                         FROM ess_request_history ERH
                                             ,ess_request_property ERP
                                        WHERE ERH.requestid = ERP.requestid
                                          AND ERH.definition = 'JobDefinition://oracle/apps/ess/custom/cclf/CCLF_DL_GL_Ledgers'
                                          AND ERH.executable_status = 'SUCCEEDED'
                                          AND ERP.name = 'submit.argument3'
                             	          AND ERP.value IS NOT NULL)))